searchButton.clickExp:
var operationInfo = {
    "formDataModelId": "/content/dam/formsanddocuments-fdm/yukon-forms/ygdirectory",
    "operationTitle": "GET /bin/yukon-forms/ygdirectory/searchEmployees",
    "operationName": "GET /bin/yukon-forms/ygdirectory/searchEmployees"
};
var inputs = {
    "keyword": searchKeyword
};
var model = this;
guidelib.dataIntegrationUtils.executeOperationV2(operationInfo, inputs, {}, function (text) {
    var result = JSON.parse(text || "{}");
    searchCount.value = result.count;
    searchTotal.value = result.total;
    searchResults.value = (result.employees || []).map(function (e) {
        return e.full_name + " <" + e.email + "> " + e.title + ", " + e.department;
    }).join("\\n");
}, null, model);

lookupEmail.valueCommitScript:
if (this.value) {
var operationInfo = {
    "formDataModelId": "/content/dam/formsanddocuments-fdm/yukon-forms/ygdirectory",
    "operationTitle": "GET /bin/yukon-forms/ygdirectory/getEmployee",
    "operationName": "GET /bin/yukon-forms/ygdirectory/getEmployee"
};
var inputs = {
    "email": lookupEmail,
    "title": lookupTitle,
    "department": lookupDepartment
};
var outputs = {
    "first_name": detFirstName,
    "last_name": detLastName,
    "email": detEmail,
    "title": detTitle,
    "department": detDepartment,
    "division": detDivision,
    "branch": detBranch,
    "unit": detUnit,
    "manager_first_name": detManagerFirstName,
    "manager_last_name": detManagerLastName,
    "manager_email": detManagerEmail
};
guidelib.dataIntegrationUtils.executeOperation(operationInfo, inputs, outputs, null, null, this);
}

